<div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Demandeur</th><th>Priorité</th><th>Statut</th><th>Mis à jour</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $tickets; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $ticket): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><a class="ticket-link" href="<?php echo e(route('tickets.show',$ticket)); ?>">#<?php echo e(str_pad($ticket->id,4,'0',STR_PAD_LEFT)); ?> · <?php echo e($ticket->title); ?></a><small><?php echo e($ticket->category); ?></small></td><td><?php echo e($ticket->requester->name); ?></td><td><span class="priority <?php echo e($ticket->priority); ?>"><?php echo e(ucfirst($ticket->priority)); ?></span></td><td><span class="status <?php echo e($ticket->status); ?>"><?php echo e(str_replace('_',' ',ucfirst($ticket->status))); ?></span></td><td><?php echo e($ticket->updated_at->diffForHumans()); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5" class="empty">Aucun ticket pour le moment.</td></tr><?php endif; ?></tbody></table></div>
